CAT_ICON = {c: c for c in ("action", "puzzle", "arcade", "casual", "strategy", "simulation", "clicker", "adventure", "shooting", "sports", "driving", "beauty", "board", "word", "skill")}

def ic(name, cls="ic", size=None):
    """Return a complete inline <svg> for the named icon (falls back to the grid icon)."""
    body = ICONS.get(name) or ICONS["grid"]
    sz = f' width="{size}" height="{size}"' if size else ""
    return f'<svg class="{cls}"{sz} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{body}</svg>'
